Task ID: java_optimistic_lock_missing
Scenario: Version field exists but update flow does not actually enforce optimistic locking.

Instructions:
Find the concurrency bug and propose the smallest production-safe fix. Assume this method is hit concurrently from two admin consoles.

Project snapshot:

=== File: src/main/java/com/example/order/Order.java ===
package com.example.order;

public class Order {
    private long id;
    private int version;
    private String status;

    public long getId() { return id; }
    public int getVersion() { return version; }
    public void setVersion(int version) { this.version = version; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
}

=== File: src/main/java/com/example/order/OrderRepository.java ===
package com.example.order;

public interface OrderRepository {
    Order require(long id);
    void updateStatus(long id, String status, int nextVersion);
}

=== File: src/main/java/com/example/order/OrderService.java ===
package com.example.order;

public class OrderService {
    private final OrderRepository orderRepository;

    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    public void approve(long orderId) {
        Order order = orderRepository.require(orderId);
        order.setStatus("APPROVED");
        orderRepository.updateStatus(order.getId(), order.getStatus(), order.getVersion() + 1);
    }
}

